// Download helpers (B3) — the one way to land generated bytes on disk.
//
// Everything funnels through lib/save.js (native save dialog + Go-side
// write; cancel resolves to "", failures reject). This module owns the
// filename → extension derivation and the three payload shapes:
//
//   downloadText(filename, mime, text)   text payloads (CSV/JSON/md/html)
//   downloadBlob(filename, blob)         binary payloads (WebM clips…)
//   downloadCanvasPNG(canvas, filename)  canvas → PNG snapshot
//
// Callers keep their own error surface (a view status line, or the
// console in views with none) — nothing here swallows a rejection.
import { saveBlob, saveText } from './save.js';

// extFromName returns the filename's extension without the dot, or the
// fallback when there is none ("archive" → "txt").
export function extFromName(filename, fallback = 'txt') {
  const name = String(filename);
  const dot = name.lastIndexOf('.');
  return dot > 0 ? name.slice(dot + 1) : fallback;
}

// downloadText saves a text payload under filename; the extension handed
// to the dialog comes from the filename itself.
export async function downloadText(filename, mime, text) {
  return saveText(filename, extFromName(filename), text, mime);
}

// downloadBlob saves a binary payload under filename (extension likewise
// derived from the filename).
export async function downloadBlob(filename, blob) {
  return saveBlob(filename, extFromName(filename), blob);
}

// downloadCanvasPNG snapshots a canvas as PNG and saves it. Rejects when
// the browser produces no blob (no encoder / zero-size canvas) or when the
// save itself fails; resolves to "" when the user cancels the dialog.
export function downloadCanvasPNG(canvas, filename) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (!blob) {
        reject(new Error('canvas snapshot produced no data'));
        return;
      }
      downloadBlob(filename, blob).then(resolve, reject);
    }, 'image/png');
  });
}
